document.addEventListener("DOMContentLoaded",()=>{let a=document.querySelectorAll("#portfolio-categories article");a.forEach(t=>{var e=t.querySelector("h2");if(e){let o=e.innerText.trim().toLowerCase().replace(/\s+/g,"-").replace(/[^a-z0-9-_]/g,"");t.addEventListener("click",e=>{a.forEach(e=>e.style.outline="none"),t.style.outline="var(--border-portfolio-categories-selected)",document.querySelectorAll("li[data-category]").forEach(e=>{var t=e.getAttribute("data-category").trim().toLowerCase();e.style.animation="none","all"===o||t===o?(e.style.display="",e.style.animation="fadeIn 0.25s ease-out forwards"):e.style.display="none"})})}})});